                }
            }
            $tp_data[&#039;TEMPLATES_SELECT&#039;] = templates_select($pr_data[&#039;tpl_name&#039;], &#039;tpl_name&#039;);
            break;

        /**
        *  default
        */
        default:
            trigger_error(&quot;invalid profile field: $field&quot;, E_USER_ERROR);
    }
}
