        if(!empty($_POST[&#039;ulogin&#039;])) DB()-&gt;query(&quot;INSERT INTO bb_ulogin VALUES (NULL, $new_user_id, &#039;&quot; . DB()-&gt;escape($_POST[&#039;ulogin&#039;]) . &quot;&#039;)&quot;);

        if (IS_ADMIN)
